return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'pt_BR','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Um plugin multiuso para exportar e importar conteúdo multilíngue.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'O gatilho de importação não aceita mais a chave na URL. Envie-a em um corpo POST.','Method Not Allowed'=>'Método não permitido','Unauthorized'=>'Não autorizado','No items to process'=>'Nenhum item para processar','No Content'=>'Sem conteúdo','Import process completed'=>'Processo de importação concluído','Success'=>'Sucesso','Import process failed'=>'O processo de importação falhou','Internal Server Error'=>'Erro interno do servidor','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d item não pôde ser processado e foi ignorado.' . "\0" . '%1$s: %2$d itens não puderam ser processados e foram ignorados.','Cleaning Up Post Data'=>'Limpando dados de post','Removing temporary and import-related post meta data.'=>'Removendo metadados de post temporários e relacionados à importação.','Cleaning Up Term Data'=>'Limpando dados de termo','Removing temporary and import-related term meta data.'=>'Removendo metadados de termo temporários e relacionados à importação.','Connecting Post Image Attachments'=>'Conectando anexos de imagem de post','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Atualizando IDs de anexos de miniatura e galeria em posts, produtos e CPTs traduzidos para apontarem para seus equivalentes traduzidos.','Connecting Inline Term Translations'=>'Conectando traduções de termos inline','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Analisando posts com um único termo de taxonomia para identificar e conectar os termos atribuídos a esses posts com suas traduções.','Deleting Obsolete Original Terms'=>'Excluindo termos originais obsoletos','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Removendo termos originais que não são mais necessários após a criação de duplicatas para termos com o mesmo nome. Garantindo que nenhum post esteja vinculado a esses termos originais.','Duplicating Terms with Shared Names Across Languages'=>'Duplicando termos com nomes compartilhados entre idiomas','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Criando duplicatas no idioma correto para termos que compartilham o mesmo nome entre idiomas, mas pertencem a posts em idiomas diferentes.','Fixing Imported Post Slugs'=>'Corrigindo slugs de posts importados','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Regenerando slugs de posts traduzidos para evitar conflitos com os originais.','Clearing Translations Cache'=>'Limpando o cache de traduções','Invalidating the persistent cache so it can be regenerated.'=>'Invalidando o cache persistente para que ele possa ser regenerado.','Marking Parent Terms for Connection'=>'Marcando termos pai para conexão','Collecting parent terms to connect their translations in the next step.'=>'Coletando termos pai para conectar suas traduções na próxima etapa.','Connecting Posts with Correct Term Translations'=>'Conectando posts com as traduções de termos corretas','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Garantindo que os posts estejam conectados a termos no idioma correto, especialmente se você tiver os mesmos nomes de termos em vários idiomas.','Sending Posts for Automatic Translation'=>'Enviando posts para tradução automática','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Criando trabalhos de tradução automática para posts marcados para tradução automática nos dados exportados.','Setting Attachments\' Language'=>'Definindo o idioma dos anexos','Assigning a language to imported attachments.'=>'Atribuindo um idioma aos anexos importados.','Updating Final Post Status'=>'Atualizando o status final do post','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Definindo o status do post com base no campo “_wpml_import_after_process_post_status” do arquivo de importação (se fornecido).','Identifying Inline Term Languages'=>'Identificando idiomas de termos inline','Identifying and setting the language of terms created during post imports.'=>'Identificando e definindo o idioma dos termos criados durante as importações de posts.','Setting Posts’ Language'=>'Definindo o idioma dos posts','Connecting posts to the default language and translations.'=>'Conectando posts ao idioma padrão e às traduções.','Setting Terms’ Language'=>'Definindo o idioma dos termos','Connecting taxonomy terms to the default (original) language and translations.'=>'Conectando termos de taxonomia ao idioma padrão (original) e às traduções.','Setting Parent Terms\' Language'=>'Definindo o idioma dos termos pai','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Atribuindo idioma aos termos de taxonomia pai que não possuem um, com base no idioma atribuído aos seus filhos.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Migrando seu site multilíngue? Lembre-se de também instalar o %s em seu novo site antes de importar seu conteúdo para que possamos restaurar todas as traduções.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Migrando sua loja multilíngue? Com o %1$s e o %2$s, você pode transferir seu conteúdo traduzido para um novo site, incluindo vendas cruzadas, vendas agregadas e atributos de produto.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Migrando sua loja multilíngue? Lembre-se de instalar o %1$s e o %2$s em seu novo site antes de importar seu conteúdo para que possamos restaurar todas as traduções.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Deseja importar seu conteúdo multilíngue? Lembre-se de instalar o %s em seu site original antes de exportar o conteúdo para que possamos importar todas as traduções aqui.','Looking to import your multilingual content? Install %1$s on this site.'=>'Deseja importar seu conteúdo multilíngue? Instale o %1$s neste site.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Lembre-se de também ativar o %2$s e o %3$s em sua loja original antes de exportar o conteúdo para que possamos importar todas as traduções aqui.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Deseja importar seu conteúdo multilíngue? Lembre-se de ativar o %1$s e o %2$s em sua loja original antes de exportar o conteúdo para que possamos importar todas as traduções aqui.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Mudar para todos os idiomas','Linking Product Attribute Translations'=>'Vinculando traduções de atributos de produto','Connecting product attributes to their translations based on associated product variations.'=>'Conectando atributos de produto às suas traduções com base nas variações de produto associadas.','Updating Related Products On Translations'=>'Atualizando produtos relacionados nas traduções','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Configurando referências de vendas agregadas, vendas cruzadas e produtos agrupados no idioma correto.','Importing Custom Attribute Labels'=>'Importando rótulos de atributos personalizados','Importing labels for product-specific (custom) attributes from the exported data.'=>'Importando rótulos para atributos específicos do produto (personalizados) dos dados exportados.','You are about to export all your products in all languages at once.'=>'Você está prestes a exportar todos os seus produtos em todos os idiomas de uma só vez.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Lembre-se de instalar o %1$s e o %2$s em seu novo site antes de importar seu conteúdo para que possamos restaurar todas as traduções.','You are about to export your products in %s.'=>'Você está prestes a exportar seus produtos em %s.','Registering Product Attributes'=>'Registrando atributos de produto','Identifying and registering attributes created during product imports for translation.'=>'Identificando e registrando atributos criados durante as importações de produtos para tradução.','Identifying Product Attribute Languages'=>'Identificando idiomas de atributos de produto','Identifying and setting the language of attributes created during product imports.'=>'Identificando e definindo o idioma dos atributos criados durante as importações de produtos.','Export and Import'=>'Exportar e Importar','I’m using the built-in %s export/import tool'=>'Estou usando a ferramenta nativa de exportação/importação do %s','I’m using %s plugin'=>'Estou usando o plugin %s','(%1$d/%2$d items)'=>'(%1$d/%2$d itens)','%d skipped'=>'%d ignorados','(no items)'=>'(sem itens)','Counting items...'=>'Contando itens...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Primeiro, diga-nos como você criará o conteúdo que será importado:','Continue'=>'Continuar','I’m using %1$s and %2$s plugins'=>'Estou usando os plugins %1$s e %2$s','I’m using a different method to export from this site'=>'Estou usando um método diferente para exportar deste site','I’m exporting the content from this site'=>'Estou exportando o conteúdo deste site','I’m exporting the content from a different website or system'=>'Estou exportando o conteúdo de um site ou sistema diferente','Before importing, add language columns to your content'=>'Antes de importar, adicione colunas de idioma ao seu conteúdo','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Certifique-se de que seu arquivo de importação inclua as seguintes colunas (campos personalizados) com informações de idioma:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Um valor que é o mesmo para todas as traduções de cada item. Em sites de e-commerce, geralmente será o SKU.','%s: The language code for each item.'=>'%s: O código do idioma para cada item.','And, you can include these two columns if needed:'=>'E você pode incluir estas duas colunas, se necessário:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Se este item for uma tradução, defina esta coluna com o código do idioma de origem. Se não for uma tradução, mantenha-a vazia.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Defina como “draft” ou “published” para determinar o status de publicação do post após o ajuste dos idiomas. Geralmente, este valor será “published”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Aqui está um exemplo de importação de dois itens nos idiomas do seu site (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Depois de adicionar as colunas de idioma ao seu arquivo de conteúdo multilíngue, importe-o para o seu site usando o plugin de importação que preferir.','Before importing, your content needs language information'=>'Antes de importar, seu conteúdo precisa de informações de idioma','%s will add the necessary language information to your export.'=>'O %s adicionará as informações de idioma necessárias à sua exportação.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importe seu arquivo de conteúdo multilíngue para o site usando o plugin de importação que preferir.','Use your favorite import plugin'=>'Use seu plugin de importação favorito','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Depois de importar o conteúdo, ele ainda não mostrará as informações de idioma corretas. Por isso, recomendamos que você importe novos conteúdos como rascunhos. Se estiver importando atualizações, poderá manter o conteúdo já publicado como publicado.','Return here, to %s, to set languages and connect translations'=>'Volte aqui, ao %s, para definir os idiomas e conectar as traduções','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Ao visitar esta página depois de importar conteúdo com informações de idioma, você poderá executar o %s para aplicar os idiomas e conectar as traduções.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Já importou e ainda vê esta tela? %1$sSolução de problemas do %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Como exportar e importar conteúdo em vários idiomas','%s is ready to update your imported content'=>'O %s está pronto para atualizar seu conteúdo importado','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Bom trabalho. Vemos %1$d termos e %2$d posts que foram importados e precisam de informações de idioma.','Good job. We see %d terms that are imported and need language information.'=>'Bom trabalho. Vemos %d termos que foram importados e precisam de informações de idioma.','Good job. We see %d posts that are imported and need language information.'=>'Bom trabalho. Vemos %d posts que foram importados e precisam de informações de idioma.','Run WPML Import'=>'Executar WPML Import','Multilingual Import Complete'=>'Importação multilíngue concluída']];